CREATE OR REPLACE FUNCTION export_table_to_csv_file ( p_query dbms_sql.varchar2a, p_separator text default ',', p_dir text DEFAULT NULL, p_filename text DEFAULT NULL, p_is_head boolean default false) RETURNS bigint AS $body$
DECLARE

    l_output        utl_file.file_type;
    l_theCursor     integer := dbms_sql.open_cursor;
    l_columnValue   varchar(4000);
    l_columnValClob text;
    l_status        integer;
    l_colCnt        bigint := 0;
    l_separator     varchar(10) := '';
    l_cnt           bigint := 0;
    l_col_desc      dbms_sql.desc_tab;
    l_offset        integer;
BEGIN
    dbms_sql.parse(
            l_theCursor
        , p_query
        , p_query.first
        , p_query.last
        , true
        , dbms_sql.native
    );

    dbms_sql.describe_columns(
            l_theCursor
        , l_colCnt
        , l_col_desc
    );

for i in 1 .. l_colCnt loop
            if l_col_desc[i].col_type = 112 then
                dbms_sql.define_column(
                        l_theCursor
                    , i
                    , l_columnValClob
                );
else
                dbms_sql.define_column(
                        l_theCursor
                    , i
                    , l_columnValue
                    , 4000
                );
end if;
end loop;

    l_status := dbms_sql.execute(l_theCursor);
    if dbms_sql.fetch_rows(l_theCursor) > 0 then
        l_output := utl_file.fopen( p_dir, p_filename, 'w', 32767 );
        if p_is_head then
            for i in 1..l_col_desc.count
                loop
                    utl_file.put(l_output, l_separator || l_col_desc[i].col_name);
                    l_separator := p_separator;
end loop;
            utl_file.new_line( l_output );
end if;

        loop
l_separator := '';
for i in 1 .. l_colCnt
                loop
                    if l_col_desc[i].col_type = 112
                    then
                        l_offset := 1;
                        dbms_sql.column_value(
                                l_theCursor
                            , i
                            , l_columnValClob
                        );
                        utl_file.put( l_output, l_separator );
                        utl_file.put( l_output, chr(34) );
                        loop
l_columnValue := replace_quote(substr(l_columnValClob, l_offset, 2000));
                            -- dbms_output.put_line(l_columnValue);
                            l_offset := l_offset + 2000;
                            utl_file.put( l_output, l_columnValue);
                            exit when trim(both l_columnValue) is null or l_offset >=30000;
end loop;
                        utl_file.put( l_output, chr(34) );
else
                        dbms_sql.column_value(
                                l_theCursor
                            , i
                            , l_columnValue
                        );
                        utl_file.put( l_output, l_separator ||  quote(l_columnValue) );
end if;

                    l_separator := p_separator;
end loop;

            utl_file.new_line( l_output );
            l_cnt := l_cnt+1;

            exit when( dbms_sql.fetch_rows(l_theCursor) <= 0 );
end loop;
end if;
    dbms_sql.close_cursor(l_theCursor);
    utl_file.fclose( l_output );
return l_cnt;
END;
