CREATE OR REPLACE FUNCTION login_has_role (p_login_id AUTH.LOGIN.ID%TYPE, p_role_id AUTH.ROLE.ID%TYPE) RETURNS bigint AS $body$
DECLARE


    v_role_cnt bigint := 0;


BEGIN

    SELECT COUNT(*) INTO STRICT v_role_cnt FROM auth.permission p
      WHERE p.login_id = p_login_id AND p.role_id = p_role_id;

    IF (v_role_cnt > 0) THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION login_has_role (p_login_id AUTH.LOGIN.ID%TYPE, p_role_id AUTH.ROLE.ID%TYPE) FROM PUBLIC;





CREATE OR REPLACE FUNCTION quote (pString text) RETURNS varchar AS $body$
BEGIN
    -- replace " or \" with \"
    return chr(34)||regexp_replace(pString,'(\\"|")','\"', 'g')||chr(34); -- fixes already quoted strings too
end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION quote (pString text) FROM PUBLIC;





